import { k8sGetQuota } from '../../lib/k8s.js';
import { Logger } from '../../logger.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';

export const k8sQuotaCommand = defineCommand({
  description: 'Show the Kubernetes resource quotas of an organisation',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [],
  async handler(options) {
    const { format, org: orgIdOrName } = options;

    const quota = await k8sGetQuota(orgIdOrName);

    switch (format) {
      case 'json':
        Logger.printJson(quota);
        break;
      case 'human':
      default: {
        const entries = Object.entries(quota?.quotas ?? {});
        if (entries.length === 0) {
          Logger.println('🔎 No Kubernetes quota found for this organisation');
          return;
        }

        Logger.println('📊 Kubernetes quotas');
        console.table(Object.fromEntries(entries.map(([name, value]) => [name, { Limit: formatValue(value) }])));
        break;
      }
    }
  },
});

function formatValue(value) {
  if (value == null) return '-';
  return typeof value === 'object' ? JSON.stringify(value) : value;
}
